440	static struct socket *geneve_create_sock(struct net *net, bool ipv6,
441						 __be16 port, bool ipv6_rx_csum)
442	{
443		struct socket *sock;
444		struct udp_port_cfg udp_conf;
445		int err;
446	
447		memset(&udp_conf, 0, sizeof(udp_conf));
448	
