451			udp_conf.ipv6_v6only = 1;
452			udp_conf.use_udp6_rx_checksums = ipv6_rx_csum;
453		} else {
454			udp_conf.family = AF_INET;
455			udp_conf.local_ip.s_addr = htonl(INADDR_ANY);
